"""Doppler pass-by detector as a single file (generated by scripts/build_standalone_doppler.py).

Finds a smooth downward glide in the pitch of an aircraft or engine tone in a recording and fits a
Doppler model: speed, closest slant distance and the time of closest approach. Results are ranges that
assume straight, level flight at constant speed and a steady tone. Offline; makes no network calls.

Needs: Python 3.10+ (tested on 3.13), numpy, scipy. ffmpeg (on PATH) only for audio that is not a WAV file, and for video.

    python doppler_standalone.py recording.wav
    python doppler_standalone.py recording.mp3 --json
"""
from __future__ import annotations

import argparse
import hashlib
import json
import shutil
import subprocess
