# --- core/spectro.py ------------------------------------------------------------------------------------
from scipy.signal import spectrogram  # noqa: E402


def compute(samples: np.ndarray, sr: int, nperseg: int = 4096):
    """Return (freqs, times, dB matrix shaped [freq, time])."""
    nperseg = min(nperseg, len(samples))
    f, t, s = spectrogram(samples, fs=sr, nperseg=nperseg, noverlap=nperseg // 2,
                          window="hann", mode="psd")
    return f, t, (10 * np.log10(s + 1e-12)).astype(np.float32)


# --- core/tracks.py -------------------------------------------------------------------------------------


STEP = 1.005   # log-frequency grid: 0.5% per bin, so a Doppler shift is a pure translation
PEN = 0.4      # dB penalty per bin of movement between frames


@dataclass
class Track:
    t: np.ndarray      # seconds
    f: np.ndarray      # Hz
    prom: np.ndarray   # dB above the frame background
    level: np.ndarray  # raw dB at the track (for the loudness-envelope check)
    span: int          # frames from first to last point, inclusive
    narrow: float = 0.0  # median dB the ridge stands above its neighbouring bins (tonality)

    @property
    def duration(self) -> float:
        return float(self.t[-1] - self.t[0])

    @property
    def coverage(self) -> float:
        return len(self.t) / max(self.span, 1)


def pick_nperseg(sr: int) -> int:
    n = 2 ** int(round(np.log2(sr * 0.18)))
    return int(min(8192, max(512, n)))


def _ridge(score: np.ndarray, maxj: int) -> np.ndarray:
    """Best smooth path through score[freq, time] (Viterbi). Returns a bin index per frame."""
    nf, nt = score.shape
    acc = score[:, 0].copy()
    back = np.zeros((nf, nt), dtype=np.int8)
    for j in range(1, nt):
        best = np.full(nf, -np.inf)
        arg = np.zeros(nf, dtype=np.int8)
        for s in range(-maxj, maxj + 1):          # previous bin = i - s
            if s == 0:
                cand = acc.copy()
            else:
                cand = np.full(nf, -np.inf)
                if s > 0:
                    cand[s:] = acc[:nf - s]
                else:
                    cand[:nf + s] = acc[-s:]
            cand -= PEN * abs(s)
            m = cand > best
            best[m], arg[m] = cand[m], s
        acc = best + score[:, j]
        back[:, j] = arg
    path = np.zeros(nt, dtype=int)
    i = int(np.argmax(acc))
    path[-1] = i
    for j in range(nt - 1, 0, -1):
        i = i - int(back[i, j])
        path[j - 1] = i
    return path


def _narrowness(res: np.ndarray, path: np.ndarray, idx: np.ndarray) -> float:
    """Median dB by which the ridge exceeds its neighbours 5-15 bins (2.5-7.5%) either side.
    Tones stand out; broadband bursts and noise do not."""
    nf = res.shape[0]
    out = []
    for j in idx:
        p = int(path[j])
        side = np.r_[res[max(0, p - 15):max(0, p - 4), j], res[p + 5:min(nf, p + 16), j]]
        if side.size:
            out.append(float(res[p, j] - np.median(side)))
    return float(np.median(out)) if out else 0.0


def _merge(tracks: list[Track], hop: float, max_gap_s: float = 2.0, tol: float = 0.02) -> list[Track]:
    """Join duplicates from overlapping segments and continuations across segment edges."""
    tracks = sorted(tracks, key=lambda tr: tr.t[0])
    out: list[Track] = []
    for tr in tracks:
        for k, o in enumerate(out):
            if tr.t[0] > o.t[-1] + max_gap_s:
                continue
            mo, mt = o.t >= tr.t[0] - 1.0, tr.t <= o.t[-1] + 1.0
            a = float(np.median(o.f[mo])) if mo.any() else float(o.f[-1])
            b = float(np.median(tr.f[mt])) if mt.any() else float(tr.f[0])
            if abs(np.log(a / b)) > tol:
                continue
            t = np.concatenate([o.t, tr.t])
            order = np.argsort(t, kind="stable")
            tu, keep = np.unique(t[order], return_index=True)
            pick = order[keep]

            def cat(u, v):
                return np.concatenate([u, v])[pick]

            out[k] = Track(t=tu, f=cat(o.f, tr.f), prom=cat(o.prom, tr.prom),
                           level=cat(o.level, tr.level),
                           span=int(round((tu[-1] - tu[0]) / hop)) + 1,
                           narrow=max(o.narrow, tr.narrow))
            break
        else:
            out.append(tr)
    return out


def trace(x: np.ndarray, sr: int, nperseg: int | None = None, fmin: float = 80.0,
          fmax: float = 5000.0, min_prom_db: float = 9.0, min_dur: float = 3.0,
          max_gap: int = 6, passes: int = 3, seg_s: float = 30.0) -> list[Track]:
    """Follow moving narrow tones. Stationary lines are removed; the clip is cut into
    overlapping segments (a single global path jumps between clutter), each pass masks the last
    ridge, and tracks that continue across segment edges are stitched back together."""
    n = nperseg or pick_nperseg(sr)
    if len(x) < n * 4:
        return []
    fhi = min(fmax, 0.95 * sr / 2)
    if fhi <= fmin * 2:
        return []
    f, t, db = compute(x, sr, n)
    rows = f <= fhi * 1.01
    f, db = f[rows], db[rows]
    grid = fmin * STEP ** np.arange(int(np.log(fhi / fmin) / np.log(STEP)))
    edges = np.clip(np.searchsorted(f, grid), 0, len(f) - 1)
    res = np.maximum.reduceat(db, edges, axis=0)      # max-pool: narrow peaks survive

    rel = res - np.median(res, axis=1, keepdims=True)   # drop anything always present
    rel -= np.median(rel, axis=0, keepdims=True)        # per-frame background
    full_score = np.clip(rel, 0, 30)

    hop = n / 2 / sr
    maxj = int(min(40, max(2, np.ceil(30 * hop))))      # allow ~15%/s of pitch change
    L = max(40, int(seg_s / hop))
    step = max(20, L // 2)
    tracks: list[Track] = []
    for s0 in range(0, max(1, rel.shape[1] - L // 2), step):
        sl = slice(s0, min(s0 + L, rel.shape[1]))
        if sl.stop - sl.start < 20:
            continue
        score = full_score[:, sl].copy()
        r, rs, tt = rel[:, sl], res[:, sl], t[sl]
        cols = np.arange(score.shape[1])
        for _ in range(passes):
            path = _ridge(score, maxj)
            prom, fpk, level = r[path, cols], grid[path], rs[path, cols]
            valid = np.flatnonzero(prom >= min_prom_db)
            runs, cur = [], []
            for i in valid:
                if cur and i - cur[-1] > max_gap:
                    runs.append(cur)
                    cur = []
                cur.append(int(i))
            if cur:
                runs.append(cur)
            for run in runs:
                if len(run) < 8:
                    continue
                idx = np.array(run)
                tracks.append(Track(t=tt[idx], f=fpk[idx], prom=prom[idx], level=level[idx],
                                    span=int(idx[-1] - idx[0] + 1),
                                    narrow=_narrowness(rs, path, idx)))
            for j, p in enumerate(path):                # mask this ridge, look for the next
                score[max(0, p - 10):p + 11, j] = 0
    tracks = [tr for tr in _merge(tracks, hop) if tr.duration >= min_dur and tr.coverage >= 0.5]
    tracks.sort(key=lambda tr: -tr.duration)
    return tracks[:8]


def _trend(tr: Track, end: bool, span_s: float = 5.0) -> tuple[float, float] | None:
    """(ln f at the track's end or start, slope of ln f per second near it), or None if too short."""
    m = (tr.t >= tr.t[-1] - span_s) if end else (tr.t <= tr.t[0] + span_s)
    if m.sum() < 4:
        return None
    t, lf = tr.t[m], np.log(tr.f[m])
    slope = float(np.polyfit(t, lf, 1)[0])
    return float(np.polyval([slope, np.mean(lf) - slope * np.mean(t)], t[-1] if end else t[0])), slope


def stitch(tracks: list[Track], max_gap_s: float = 9.0, tol: float = 0.035) -> list[Track]:
    """Join pieces of one glide that a burst of broadband noise cut apart.

    Two tracks are joined when the second starts after the first ends (within max_gap_s) and the pitch
    change across the gap matches the slope of both ends (a pass-by glide is smooth): the straight
    extrapolation of each across the gap must land within `tol` (a ratio of 3.5%) of the other. The
    joined track keeps only real measurements (the gap is left empty), so downstream checks still see it
    as broken there. Pieces of different harmonics are not joined (their pitch differs by far more)."""
    pool = sorted(tracks, key=lambda tr: tr.t[0])
    changed = True
    while changed:
        changed = False
        best = None
        for i, a in enumerate(pool):
            ta = _trend(a, end=True)
            if ta is None:
                continue
            for j, b in enumerate(pool):
                if i == j or not 0.0 < b.t[0] - a.t[-1] <= max_gap_s:
                    continue
                tb = _trend(b, end=False)
                if tb is None:
                    continue
                gap = float(b.t[0] - a.t[-1])
                (la, sa), (lb, sb) = ta, tb
                s = 0.5 * (sa + sb)
                resid = abs((lb - la) - s * gap)
                forward = abs(la + sa * gap - lb)
                backward = abs(lb - sb * gap - la)
                if max(forward, backward) <= tol + 0.5 * abs(s) * gap * 0.15 and resid <= tol and sa * sb >= -1e-6:
                    if best is None or resid < best[0]:
                        best = (resid, i, j)
        if best:
            _, i, j = best
            a, b = pool[i], pool[j]
            hop = float(np.median(np.diff(np.concatenate([a.t, b.t])))) if len(a.t) + len(b.t) > 3 else 0.2
            merged = Track(t=np.concatenate([a.t, b.t]), f=np.concatenate([a.f, b.f]),
                           prom=np.concatenate([a.prom, b.prom]), level=np.concatenate([a.level, b.level]),
                           span=int(round((b.t[-1] - a.t[0]) / max(hop, 1e-3))) + 1, narrow=max(a.narrow, b.narrow))
            pool = [tr for k, tr in enumerate(pool) if k not in (i, j)] + [merged]
            pool.sort(key=lambda tr: tr.t[0])
            changed = True
    return pool


# --- core/combfit.py ------------------------------------------------------------------------------------
"""Matched-filter Doppler detector: find faint, noisy pass-bys that ridge tracking loses.

The ridge tracker follows one narrow line through the spectrogram, and a burst of wind or traffic noise
cuts that line apart. This detector instead *integrates*: for every candidate pass (speed, closest
distance, time of closest approach, base pitch) it adds up the spectrogram along the whole predicted
curve and along its harmonics, so a faint line that is invisible frame by frame still adds up.

Noise has no preferred direction but an aircraft only ever glides *down* (approach then recession), so the
same scan is repeated with the curve mirrored upward. A pass shows as a downward score well above the
best upward score, and that ratio, not an absolute threshold, is the evidence. The best candidates are
then refined: a ridge is followed along the predicted curve, a Doppler model is fitted to it, and its
numbers are reported. Speed is usually within about 30% in tests; distance is rougher.
"""


MF_STEP = 1.01
MF_LN = float(np.log(MF_STEP))
MF_FMIN, MF_FMAX = 50.0, 1600.0
MF_BETAS = (0.04, 0.07, 0.11, 0.17, 0.26, 0.4)           # speed / speed of sound
MF_TAUS = (1.5, 3.0, 6.0, 12.0, 24.0, 48.0)              # closest-approach distance / speed (s)
MF_MIN_RATIO = 1.6                                       # downward score / best upward score
MF_F0_LO, MF_F0_HI = 80.0, 500.0                            # base pitch range of the harmonic comb (Hz)


def zmap(x: np.ndarray, sr: int, nper_s: float = 0.35):
    """Log-frequency map of how far each cell stands above its frame and frequency background."""
    nper = int(2 ** round(np.log2(sr * nper_s)))
    f, t, db = compute(x, sr, nper)
    sel = (f >= MF_FMIN * 0.8) & (f <= MF_FMAX)
    f, db = f[sel], db[sel]
    if len(f) < 8:
        return None
    db = db - np.median(db, axis=0, keepdims=True)      # broadband bursts raise every bin of a frame
    db = db - np.median(db, axis=1, keepdims=True)      # lines that are always present (hum, machinery)
    mad = float(np.median(np.abs(db))) * 1.4826 + 1e-9
    z = np.clip(db / mad, -2, 12)
    yf = MF_FMIN * MF_STEP ** np.arange(int(np.log(MF_FMAX / MF_FMIN) / MF_LN))
    return yf, t, np.stack([np.interp(yf, f, z[:, j]) for j in range(z.shape[1])], axis=1)


def harmonic_sum(z: np.ndarray, k_max: int = 3) -> np.ndarray:
    """Cell i collects the energy at i, 2i, 3i (in frequency): a harmonic comb stacks faint lines."""
    h = np.zeros_like(z)
    for k in range(1, k_max + 1):
        off = int(round(np.log(k) / MF_LN))
        if off < z.shape[0]:
            h[:z.shape[0] - off] += z[off:]
    return h / np.sqrt(k_max)


def scan(h: np.ndarray, t: np.ndarray, sign: int = 1, step_t0: float = 1.0,
         margin: float = 10.0) -> list[tuple[float, float, float, float, int]]:
    """[(score, beta, tau, t0, base pitch bin)] for every (beta, tau, t0): the best base pitch of each."""
    dt = float(t[1] - t[0])
    cols = np.arange(0, h.shape[1], max(1, int(round(0.35 / dt))))
    tc = t[cols]
    lo = int(np.log(MF_F0_LO / MF_FMIN) / MF_LN)
    n_f0 = int(np.log(MF_F0_HI / MF_F0_LO) / MF_LN)
    base = np.arange(n_f0)[:, None] + lo
    margin = min(margin, 0.2 * float(tc[-1] - tc[0]))
    out = []
    for beta in MF_BETAS:
        for tau in MF_TAUS:
            for t0 in np.arange(tc[0] + margin, tc[-1] - margin, step_t0):
                u = (tc - t0) / tau
                g = 1 / (1 + sign * beta * u / np.sqrt(1 + u * u))
                idx = base + np.round(np.log(g) / MF_LN).astype(int)[None, :]
                ok = (idx >= 0) & (idx < h.shape[0])
                vals = np.where(ok, h[np.clip(idx, 0, h.shape[0] - 1), cols[None, :]], 0.0)
                sc = vals.sum(axis=1) / np.sqrt(len(tc))
                i = int(np.argmax(sc))
                out.append((float(sc[i]), beta, tau, float(t0), i + lo))
    return out


def refine(yf, t, z, cand, fit_doppler, k_max: int = 5, band: float = 0.05, zmin: float = 2.5) -> dict | None:
    """Follow a ridge along the candidate curve (best harmonic), fit the Doppler model, return its numbers."""
    _, beta, tau, t0, i0 = cand
    f0 = yf[min(i0, len(yf) - 1)]
    u = (t - t0) / tau
    g = 1 / (1 + beta * u / np.sqrt(1 + u * u))
    best = None
    for k in range(1, k_max + 1):
        yi = (np.log(k * f0 * g) - np.log(yf[0])) / MF_LN
        if yi.min() < 3 or yi.max() > len(yf) - 4:
            continue
        e = float(z[np.clip(np.round(yi).astype(int), 0, len(yf) - 1), np.arange(len(t))].sum())
        if best is None or e > best[0]:
            best = (e, k)
    if best is None:
        return None
    k = best[1]
    pred = np.log(k * f0 * g)
    w = int(round(band / MF_LN))
    pts = []
    for j in range(len(t)):
        c = int(round((pred[j] - np.log(yf[0])) / MF_LN))
        a, b = max(0, c - w), min(len(yf), c + w + 1)
        if b - a < 3:
            continue
        seg = z[a:b, j]
        m = int(np.argmax(seg))
        if seg[m] >= zmin:
            pts.append((t[j], yf[a + m], seg[m]))
    if len(pts) < 20:
        return None
    tt, ff, zz = map(np.array, zip(*pts))
    if tt[-1] - tt[0] < 10:
        return None
    fit = fit_doppler(tt, ff)
    if not fit:
        return None
    p, r2 = fit
    return dict(t0=float(p[2]), beta=float(p[1]), tau=float(p[3]), r2=float(r2), n=len(tt), harmonic=k,
                t_start=float(tt[0]), t_end=float(tt[-1]), hi=float(np.median(ff[:5])), lo=float(np.median(ff[-5:])),
                zmean=float(zz.mean()))


def detect(x: np.ndarray, sr: int, fit_doppler, offset: float = 0.0, max_events: int = 3) -> list[dict]:
    """Candidate passes in one chunk of audio, best first. Each has `ratio` (down vs up evidence) and the
    refined Doppler numbers; only candidates with ratio >= MF_MIN_RATIO and a successful fit are returned."""
    zm = zmap(x, sr)
    if zm is None or len(zm[1]) < 40:
        return []
    yf, t, z = zm
    h = harmonic_sum(z)
    long_chunk = (t[-1] - t[0]) > 150
    down = scan(h, t, +1, step_t0=2.0 if long_chunk else 1.0)
    up = scan(h, t, -1, step_t0=2.0 if long_chunk else 1.0)
    if not down or not up:
        return []
    best_up = max(c[0] for c in up)
    out, taken = [], []
    for cand in sorted(down, reverse=True):
        if len(out) >= max_events or cand[0] / best_up < MF_MIN_RATIO:
            break
        if any(abs(cand[3] - t1) < 20.0 for t1 in taken):
            continue
        taken.append(cand[3])
        r = refine(yf, t, z, cand, fit_doppler)
        if not r:
            continue
        r.update(ratio=float(cand[0] / best_up), t0_template=float(cand[3]))
        for key in ("t0", "t_start", "t_end", "t0_template"):
            r[key] += offset
        out.append(r)
    return out

matched_filter = detect


# --- core/audio.py --------------------------------------------------------------------------------------


warnings.filterwarnings("ignore", category=wavfile.WavFileWarning)   # extra RIFF chunks are harmless

MAX_SECONDS = 300          # per analysis chunk
MAX_TOTAL = 3 * 3600       # longest stretch decoded/scanned
SILENCE = 1e-5             # peak below this counts as digital silence


class AudioError(RuntimeError):
    """Audio could not be loaded (missing ffmpeg, no audio stream, bad file)."""


def _to_float(data: np.ndarray) -> np.ndarray:
    if data.dtype == np.uint8:
        x = (data.astype(np.float32) - 128) / 128
    elif np.issubdtype(data.dtype, np.integer):
        x = data.astype(np.float32) / float(np.iinfo(data.dtype).max + 1)
    else:
        x = data.astype(np.float32)
    return x.mean(axis=1) if x.ndim > 1 else x


def _read_wav(path: Path, offset: float = 0.0, duration: float = MAX_SECONDS):
    sr, data = wavfile.read(path, mmap=True)
    a = int(max(offset, 0.0) * sr)
    return _to_float(np.asarray(data[a:a + int(duration * sr)])), int(sr)


def _wav_path(path: Path) -> Path:
    """A WAV scipy can mmap: the file itself, else an ffmpeg-decoded cached copy."""
    path = Path(path)
    if path.suffix.lower() == ".wav":
        try:
            wavfile.read(path, mmap=True)
            return path
        except Exception:
            pass  # unusual WAV encoding: fall through to ffmpeg
    return _ffmpeg_to_wav(path)


def total_seconds(path: Path) -> float:
    try:
        sr, data = wavfile.read(_wav_path(path), mmap=True)
        return len(data) / sr
    except AudioError:
        raise
    except Exception as e:
        raise AudioError(f"Could not read audio: {e}")


def sound_start(path: Path, block: float = 5.0) -> float:
    """Seconds of leading digital silence to skip (0 if the file starts with sound)."""
    w = _wav_path(path)
    sr, data = wavfile.read(w, mmap=True)
    n = int(block * sr)
    for a in range(0, min(len(data), int(MAX_TOTAL * sr)), n):
        if np.abs(_to_float(np.asarray(data[a:a + n]))).max(initial=0.0) > SILENCE:
            return max(0.0, a / sr - 1.0)
    return 0.0


def _ffmpeg_to_wav(path: Path) -> Path:
    exe = shutil.which("ffmpeg")
    if not exe:
        raise AudioError("This format needs ffmpeg: sudo apt install ffmpeg")
    st = path.stat()
    key = hashlib.sha1(f"{path.resolve()}|{st.st_mtime_ns}|{st.st_size}".encode()).hexdigest()[:16]
    cache = Path(tempfile.gettempdir()) / "mitraav-cache"
    cache.mkdir(exist_ok=True)
    out = cache / f"{key}.wav"
    if not out.exists():
        tmp = cache / f"{key}.part.wav"
        cmd = [exe, "-v", "error", "-y", "-i", str(path), "-vn", "-ac", "1",
               "-t", str(MAX_TOTAL), "-c:a", "pcm_s16le", str(tmp)]
        try:
            r = subprocess.run(cmd, capture_output=True, text=True, timeout=600)
        except subprocess.TimeoutExpired:
            raise AudioError("ffmpeg timed out decoding the file")
        if r.returncode != 0 or not tmp.exists():
            raise AudioError(f"ffmpeg could not decode audio: {r.stderr.strip()[:200]}")
        tmp.replace(out)
    return out


def load_audio(path: Path, offset: float | None = None,
               duration: float = MAX_SECONDS) -> tuple[np.ndarray, int]:
    """Mono float32 samples in [-1, 1] and the sample rate: `duration` seconds from `offset`.
    With offset=None, leading digital silence is skipped (see sound_start)."""
    path = Path(path)
    try:
        if offset is None:
            offset = sound_start(path)
        return _read_wav(_wav_path(path), offset, duration)
    except AudioError:
        raise
    except Exception as e:
        raise AudioError(f"Could not read audio: {e}")


def iter_chunks(path: Path, chunk: float = MAX_SECONDS, overlap: float = 30.0):
    """Yield (offset_s, samples, sr) over the whole file after leading silence. Silent chunks are
    skipped. Chunks overlap so an event on a boundary is seen whole at least once."""
    path = Path(path)
    try:
        w = _wav_path(path)
        total = min(total_seconds(path), MAX_TOTAL)
        start = sound_start(path)
        step = max(chunk - overlap, 1.0)
        off = start
        first = True
        while first or off < total - 5.0:            # a short clip is one chunk, never none
            first = False
            x, sr = _read_wav(w, off, chunk)
            if len(x) and np.abs(x).max() > SILENCE:
                yield off, x, sr
            if off + chunk >= total:
                break
            off += step
    except AudioError:
        raise
    except Exception as e:
        raise AudioError(f"Could not read audio: {e}")


# --- probes/doppler.py ----------------------------------------------------------------------------------


C = 343.0                    # speed of sound, m/s
WINDOWS = (0.12, 0.35, 0.9)  # analysis window lengths (s): fast sweeps need short, slow curves long
FMAX = 1500.0                # aircraft/engine tones live here; above it birdsong dominates
MIN_NARROW_DB = 8.5          # ridge must stand this far above neighbouring bins
MAX_SLOPE = 0.09             # 90th percentile |d ln f / dt| (per s)
MAX_JITTER = 0.013           # 90th percentile deviation from a running median
MIN_SLANT_M = 100.0          # a 'closest distance' below this is a near-step fit, not a measurement
MF_MAX_CHUNKS = 6            # chunks (5 min each) the matched-filter detector scans
MAX_UP = 0.15                # lone tracks that step up and down are machinery, not glides
MIN_RATIO = 1.08             # smaller glides are indistinguishable from drifting noise


def doppler_model(t, f0, beta, t0, tau):
    """Source passing at constant speed beta*C; tau = closest-approach distance / speed.

    t is the time the tone is *heard*, and t0 is when the closest-approach tone is heard. The sound
    emitted at time te arrives at te + r(te)/C, so the curve is solved for the emission time in
    closed form (the arrival equation is a quadratic in the along-track offset s):
        s + beta*sqrt(tau^2 + s^2) = tau_o   ->   s = (tau_o - beta*sqrt(tau_o^2 + (1-beta^2) tau^2)) / (1-beta^2)
    with tau_o = (t - t0) + beta*tau. Ignoring the travel delay (the older simplification) biases the
    distance and speed of fast, close pass-bys.
    """
    beta = np.minimum(beta, 0.95)
    tau_o = (t - t0) + beta * tau
    k = 1 - beta * beta
    s = (tau_o - beta * np.sqrt(tau_o * tau_o + k * tau * tau)) / k
    return f0 / (1 + beta * s / np.sqrt(tau * tau + s * s))


def fit_doppler(t: np.ndarray, f: np.ndarray):
    if len(t) > 300:
        i = np.linspace(0, len(t) - 1, 300).astype(int)
        t, f = t[i], f[i]
    k = max(3, len(f) // 10)
    hi, lo = float(np.median(f[:k])), float(np.median(f[-k:]))
    dur = float(t[-1] - t[0])
    g = np.gradient(median_filter(f, size=5, mode="nearest"), t)
    p0 = [np.sqrt(hi * lo), float(np.clip((hi - lo) / (hi + lo), 0.02, 0.7)),
          float(t[int(np.argmin(g))]), max(dur / 6, 0.2)]
    bounds = ([f.min() * 0.5, 0.005, t[0] - dur, 0.05], [f.max() * 2, 0.9, t[-1] + dur, 120.0])
    try:
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            popt, _ = curve_fit(doppler_model, t, f, p0=p0, bounds=bounds,
                                x_scale="jac", maxfev=4000)
    except (RuntimeError, ValueError):
        return None
    ss_res = float(np.sum((f - doppler_model(t, *popt)) ** 2))
    ss_tot = float(np.sum((f - f.mean()) ** 2))
    return popt, 1 - ss_res / max(ss_tot, 1e-12)


def level_peaks_at_t0(tr: Track, t0: float, dur: float) -> bool:
    """A real pass-by is loudest near closest approach and quieter at both ends."""
    lv = median_filter(tr.level, size=5, mode="nearest")
    k = max(3, len(lv) // 10)
    i = int(np.argmax(lv))
    ends = max(float(np.median(lv[:k])), float(np.median(lv[-k:])))
    return abs(float(tr.t[i]) - t0) <= 0.35 * dur and float(lv[i]) - ends >= 3.0


def clean_ridge(tr: Track) -> bool:
    """A real tone ridge is narrow and smooth. Chains hopping through noise bursts, transients
    or wind are not: they jitter, change pitch implausibly fast, or barely exceed their
    neighbouring bins. (Thresholds from the real demo clip and the synthetic samples.)"""
    if tr.narrow < MIN_NARROW_DB:
        return False
    f, t = tr.f, tr.t
    dt = np.diff(t)
    ok = dt <= 3 * float(np.median(dt)) + 1e-9
    if not ok.any():
        return False
    slope = np.abs(np.diff(np.log(f)))[ok] / np.maximum(dt[ok], 1e-9)
    jit = np.abs(np.log(f) - np.log(median_filter(f, size=9, mode="nearest")))
    return float(np.percentile(slope, 90)) <= MAX_SLOPE and float(np.percentile(jit, 90)) <= MAX_JITTER


def _up_fraction(f: np.ndarray) -> float:
    """Share of total pitch movement that goes upward: ~0 for a glide, higher for lines that
    step up and down (machinery, speed-controlled fans)."""
    d = np.diff(np.log(median_filter(f, size=5, mode="nearest")))
    return float(d[d > 0].sum() / max(np.abs(d).sum(), 1e-9))


def evaluate(tr: Track):
    if not clean_ridge(tr):
        return None
    f = median_filter(tr.f, size=5, mode="nearest")
    t = tr.t
    k = max(3, len(f) // 10)
    hi, lo = float(np.median(f[:k])), float(np.median(f[-k:]))
    if lo <= 0 or not MIN_RATIO <= hi / lo <= 3.0:
        return None
    if not float(spearmanr(t, f)[0]) <= -0.85:
        return None
    fit = fit_doppler(t, f)
    if not fit:
        return None
    popt, r2 = fit
    if r2 < 0.85:
        return None
    dur = float(t[-1] - t[0])
    if dur < 4.0:
        return None
    t0, tau = float(popt[2]), float(popt[3])
    return dict(hi=hi, lo=lo, r2=r2, beta=float(popt[1]), beta_lb=(hi - lo) / (hi + lo),
                t0=t0, tau=tau, dur=dur, t_start=float(t[0]), t_end=float(t[-1]), support=1, narrow=float(tr.narrow), up=_up_fraction(f),
                sat=bool(tau <= 0.5 * dur and t[0] < t0 < t[-1] and popt[1] * C * tau >= MIN_SLANT_M),
                level_ok=level_peaks_at_t0(tr, t0, dur))


def _same_event(e: dict, k: dict) -> bool:
    """Same pass-by: closest-approach times agree, or the spans overlap with a matching
    pitch ratio (harmonics of one source glide by the same ratio)."""
    if abs(e["t0"] - k["t0"]) <= max(6.0, 0.25 * max(e["dur"], k["dur"])):
        return True
    ov = min(e["t_end"], k["t_end"]) - max(e["t_start"], k["t_start"])
    if ov < 0.5 * min(e["dur"], k["dur"]):
        return False
    return abs(np.log(e["hi"] / e["lo"]) - np.log(k["hi"] / k["lo"])) < 0.1


def dedupe(evals: list[dict]) -> list[dict]:
    """Overlapping analysis chunks see the same track twice; that is not harmonic support."""
    out: list[dict] = []
    for e in sorted(evals, key=lambda e: -e["r2"]):
        if not any(abs(e["t_start"] - k["t_start"]) < 3.0 and abs(e["t_end"] - k["t_end"]) < 3.0
                   and abs(np.log(e["hi"] / k["hi"])) < 0.04 for k in out):
            out.append(e)
    return out


def group_events(evals: list[dict]) -> list[dict]:
    """Harmonics and repeated detections of one event are merged; support counts them."""
    kept: list[dict] = []
    for e in sorted(evals, key=lambda e: -(e["r2"] * min(e["dur"], 10))):
        for k in kept:
            if _same_event(e, k):
                k["support"] += 1
                break
        else:
            kept.append(e)
    # a lone track (no harmonic partner) must be a long, clear glide to count
    kept = [k for k in kept if k["support"] > 1 or (k["dur"] >= 8.0 and k["hi"] / k["lo"] >= 1.15)]
    return sorted(kept, key=lambda e: e["t0"])


def matched_event(r: dict) -> dict:
    """An event dict (same keys as evaluate) from a refined matched-filter candidate."""
    dur = r["t_end"] - r["t_start"]
    beta, tau = r["beta"], r["tau"]
    return dict(hi=r["hi"], lo=r["lo"], r2=r["r2"], beta=beta, beta_lb=(r["hi"] - r["lo"]) / (r["hi"] + r["lo"]),
                t0=r["t0"], tau=tau, dur=dur, t_start=r["t_start"], t_end=r["t_end"], support=1, narrow=r["ratio"], up=0.0,
                sat=bool(tau <= 0.5 * dur and r["t_start"] < r["t0"] < r["t_end"] and beta * C * tau >= MIN_SLANT_M
                         and 0.03 <= beta <= 0.6),
                level_ok=False, matched=True, ratio=r["ratio"], harmonic=r["harmonic"])


def merge_matched(events: list[dict], matched: list[dict]) -> list[dict]:
    """Add the matched-filter events to the tracker's. Where both see the same pass (closest approaches within
    8 s) the tracker's event is kept, and if it could only give a lower bound while the matched fit gives
    numbers, those numbers are attached. A matched event alone is kept when its evidence ratio is high."""
    out = [dict(e) for e in events]
    for m in matched:
        near = [e for e in out if abs(e["t0"] - m["t0"]) <= max(8.0, 0.2 * max(e["dur"], m["dur"]))]
        if near:
            e = near[0]
            e["confirmed"] = True
            if not e["sat"] and m["sat"]:
                e.update(beta=m["beta"], tau=m["tau"], sat=True, from_matched=True)      # the tracker keeps its own time
            continue
        out.append(m)
    return sorted(out, key=lambda e: e["t0"])


def describe(i: int, e: dict) -> str:
    s = f"**event {i}**: closest approach heard near {e['t0']:.0f} s, pitch {e['hi']:.0f} to {e['lo']:.0f} Hz"
    if e.get("matched"):
        s += f" (found by integrating along the predicted curve, evidence {e['ratio']:.1f}x the best upward glide)"
    elif e.get("from_matched"):
        s += " (numbers from a fit to the whole curve)"
    if e["support"] > 1:
        s += f" ({e['support']} matching tracks, e.g. harmonics)"
    if e["sat"]:
        v = e["beta"] * C
        s += (f", about **{v:.0f} m/s** ({v * 3.6:.0f} km/h), closest slant distance "
              f"about **{v * e['tau']:.0f} m**")
    else:
        v = e["beta_lb"] * C
        s += (f", speed at least **{v:.0f} m/s** ({v * 3.6:.0f} km/h); the curve is too flat to "
              "pin down speed or distance")
    return s


class DopplerProbe(Probe):
    name = "doppler_pass"
    group = "Aircraft and motion"
    clutter_sensitive = True
    masked_by = ("sirens",)
    media = (MediaType.AUDIO, MediaType.VIDEO)
    timeout = 900.0

    def run(self, path: Path) -> Finding:
        tracks: list[Track] = []
        matched: list[dict] = []
        n_chunks = 0
        try:
            for off, x, sr in iter_chunks(path):
                if len(x) / sr < 5 or sr < 2000:
                    continue
                n_chunks += 1
                if n_chunks <= MF_MAX_CHUNKS:
                    matched += [matched_event(r) for r in matched_filter(x, sr, fit_doppler, offset=off)
                                if r["r2"] >= 0.9 and r["t_end"] - r["t_start"] >= 12]
                for w in WINDOWS:
                    found = trace(x, sr, nperseg=int(2 ** round(np.log2(sr * w))), fmax=FMAX)
                    for tr in found:
                        tr.t = tr.t + off          # report file-absolute time
                    tracks += found
                    tracks += [tr for tr in stitch(found) if all(tr is not f for f in found)]   # glides cut apart by bursts
        except AudioError as e:
            return Finding(probe=self.name, detected=False, status="not_run", detail=str(e))
        if not n_chunks:
            return Finding(probe=self.name, detected=False, status="not_run",
                           detail="No usable audio: need at least 5 s of non-silent audio "
                                  "sampled at 2 kHz or more")
        evals = [e for e in map(evaluate, tracks) if e] if tracks else []
        events = group_events(dedupe(evals)) if evals else []
        events = merge_matched(events, matched)
        if not events:
            if not tracks:
                msg = ("No sustained moving tone found. Jet pass-bys are broadband and often show no clean tone; "
                       "propellers, rotors, horns and engines do. Very faint curves can also be hidden: boost levels "
                       "and check the spectrogram by eye.")
            elif not evals:
                msg = (f"{len(tracks)} moving tone track(s) found, none shaped like a pass-by "
                       "(a smooth downward glide of 8-200% pitch change).")
            else:
                msg = (f"{len(evals)} glide(s) found but none long or consistent enough to be a "
                       "pass-by (isolated tracks need 8 s and a 15% pitch change).")
            return Finding(probe=self.name, detected=False, summary=msg)
        strong = [e for e in events if e["support"] > 1 or (e["sat"] and e["up"] <= MAX_UP) or e.get("confirmed")
                  or (e.get("matched") and e["ratio"] >= 2.2)]
        weak = [e for e in events if e not in strong]
        if not strong:       # keep the best lone track so something is reported, flagged weak
            strong, weak = [max(events, key=lambda e: e["r2"] * min(e["dur"], 10))], []
            weak = [e for e in events if e not in strong]
        events = strong
        best = max(events, key=lambda e: e["r2"] * min(e["dur"], 10))
        quality = min(1.0, max(0.0, (best["r2"] - 0.85) / 0.15))
        strength = 0.25 + 0.5 * quality + 0.25 * min(1.0, best["dur"] / 8)
        if best["level_ok"]:
            strength = min(1.0, strength + 0.1)
        if not best["sat"]:
            strength *= 0.6
        if len(events) > 1:
            strength = min(1.0, strength + 0.05 * (len(events) - 1))

        notes = [describe(i + 1, e) for i, e in enumerate(events)]
        if weak:
            notes.append("weaker candidates (single flat tracks, check the spectrogram by eye; "
                         "stepping machinery lines can mimic them) near "
                         + ", ".join(f"{e['t0']:.0f} s" for e in weak))
        cons = ["source type"] + (["speed", "distance"] if any(e["sat"] for e in events) else [])
        if len(events) > 1:
            gaps = [f"{b['t0'] - a['t0']:.0f} s" for a, b in zip(events, events[1:])]
            notes.append("offset between strong events' closest-approach times: " + ", ".join(gaps))
            cons.append("time")
        if not best["sat"]:
            notes.append("a siren sweep, slowing engine or speed-changed audio fits a flat "
                         "glide equally well")
        notes.append("Audio alone cannot identify the aircraft. Match speed, slant distance "
                     "(not ground distance) and the offset against ADS-B tracks, shifting each "
                     "track's closest-approach time later by slant distance / 343 m/s")
        notes.append("the fit models the sound-travel delay but assumes straight, level flight at "
                     "constant speed and a steady engine tone, so treat numbers as ranges")
        regions = [dict(label=f"event {i + 1}: {e['hi']:.0f}→{e['lo']:.0f} Hz near {e['t0']:.0f} s",
                        t0=max(0.0, e["t_start"] - 15), t1=e["t_end"] + 15,
                        t_play=max(0.0, e["t_start"] - 3),
                        f0=max(20.0, 0.7 * e["lo"]), f1=1.4 * e["hi"])
                   for i, e in enumerate(events)]
        regions += [dict(label=f"weak candidate near {e['t0']:.0f} s",
                         t0=max(0.0, e["t_start"] - 15), t1=e["t_end"] + 15,
                        t_play=max(0.0, e["t_start"] - 3),
                         f0=max(20.0, 0.7 * e["lo"]), f1=1.4 * e["hi"]) for e in weak]
        return Finding(probe=self.name, detected=True, strength=strength, narrows=0.3,
                       regions=regions,
                       constrains=cons, effort=3, follow_ups=FOLLOW_UPS,
                       summary=" • ".join(notes) + ".")


# --- command line -----------------------------------------------------------------------------------------


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description="Doppler pass-by detector (standalone)")
    ap.add_argument("file", type=Path, help="audio file (WAV needs nothing else; other formats and video need ffmpeg)")
    ap.add_argument("--json", action="store_true", help="print the result as JSON")
    args = ap.parse_args(argv)
    if not args.file.is_file():
        ap.error(f"not a file: {args.file}")
    f = DopplerProbe().run(args.file)
    if args.json:
        print(json.dumps(asdict(f), indent=2, default=str))
        return 0
    if f.status != "ok":
        print(f"not run: {f.detail}")
        return 1
    print(("FOUND" if f.detected else "nothing found") + (f" (strength {f.strength:.2f})" if f.detected else ""))
    print(f.summary.replace("**", ""))
    for r in f.regions:
        print(f"  signal: {r['label']} (listen from about {r.get('t_play', r['t0']):.0f} s)")
    for u in f.follow_ups:
        print(f"  -> {u.name}: {u.url}  {u.note}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
